export type SourceName = "CrowdStrike" | "SentinelOne" | "Intune" | "Jamf" | "SOTI" | "Absolute Secure Endpoint" | "Portnox AgentP" | "EntraID" | "Active Directory" | "Okta" | "Google Workspace";
export type SourceStatus = 'Reporting' | 'Stale' | 'Pending' | 'Not present' | 'N/A';
export type AuthRepository = 'Active Directory' | 'EntraID' | 'Okta' | 'Google Workspace' | null;
export type RiskViolation = "Administrator privileges" | "Antivirus" | "Applications" | "Certificates" | "Geolocation" | "Peripheral devices" | "Rootkit" | "Running services" | "Windows registry" | "Generative AI";

export interface SourceCoverageCell {
  status: SourceStatus;
  lastSyncAt: string | null;
}

export type SourceCoverage = Record<SourceName, SourceCoverageCell>;

export interface SourceFieldValue {
  value: string | null;
  hasConflict: boolean;
  valuesBySource: Record<string, string | null>;
  fieldNamesBySource?: Record<string, string>;
}

export interface AccountRecord {
  id: number;
  name: string;
  accountType: 'LDAP' | 'Cloud' | 'MAC' | null;
  group: string | null;
  description?: string;
  credentialsExpire?: string;
  createdBy?: string;
  allowDevicesWithoutAgentP?: boolean;
  totalMacAddresses?: number | null;
  totalMacVendors?: number | null;
  location: string | null;
  authType: string | null;
  authRepo: AuthRepository;
  nasSite: string | null;
  byAdmin: string | null;
  byPolicy: string | null;
  sourceCoverage: SourceCoverage;
  sourceFieldValues: Record<string, SourceFieldValue>;
}

export interface DeviceRecord {
  id: number;
  name: string;
  type: 'Laptop' | 'Desktop' | 'Server' | 'Mobile' | 'IoT/Printer';
  os: string;
  location: string | null;
  account: string;
  accountType: 'LDAP' | 'Cloud' | 'MAC' | null;
  group: string | null;
  riskScore: number | null;
  status: 'Blocked' | 'Archived' | 'No issues' | null;
  bAdmin: string | null;
  bPolicy: string | null;
  bRisk: number | null;
  bAcct: boolean;
  lastConnectedAt: string | null;
  createdAt: string | null;
  coverageGaps: string[];
  authType: string | null;
  authRepo: AuthRepository;
  nasSite: string | null;
  macVendor: string;
  manufacturer: string | null;
  model: string | null;
  applications: string[];
  patches: string[];
  processes: string[];
  services: string[];
  peripherals: string[];
  browser: string[];
  browserExtensions: string[];
  agentVersion: string | null;
  enrolledAt: string | null;
  agentpVersion: string | null;
  riskPolicy: string | null;
  accessPolicy: string | null;
  riskViolations: RiskViolation[];
  nasIp: string | null;
  agentpLastReported: string | null;
  sourceCoverage: SourceCoverage;
  sourceFieldValues: Record<string, SourceFieldValue>;
}

